           options: [
             { id: "typescript", label: "TypeScript", description: "Adds static typing on top of JavaScript." },
             { id: "lua", label: "Lua", description: "A lightweight embedded language with dynamic typing." },
             { id: "kotlin", label: "Kotlin", description: "A statically typed language for JVM and Android." },
             { id: "perl", label: "Perl", description: "A flexible scripting language with dynamic typing." },
           ],
         },
       ];

       function createElement(tag, className, text) {
         const el = document.createElement(tag);
         if (className) el.className = className;
         if (text !== undefined) el.textContent = text;
         return el;
       }

       function AnswerOption(questionId, option) {
         const label = createElement("label", "option");
         const input = document.createElement("input");
         input.type = "checkbox";
         input.name = questionId;
         input.value = option.id;

         const content = createElement("div", "option-label");
         const title = createElement("strong", null, option.label);
         const description = createElement("span", null, option.description);

         content.append(title, description);
         label.append(input, content);
         return label;
       }

       function QuizQuestion(question) {
         const field = createElement("div", "form-field");
         const head = createElement("div", "question-head");
         const title = createElement("h2", "question-title", question.question);
         head.append(title);

         if (question.helpText) {
           head.append(createElement("p", "help-text", question.helpText));
         }

         const options = createElement("div", "options");
         question.options.forEach((option) => {
           options.append(AnswerOption(question.id, option));
         });

         field.append(head, options);
         return field;
       }

       function App() {
         const shell = createElement("main", "app-shell");

         const hero = createElement("header", "hero");
         hero.append(
           createElement("div", "eyebrow", "Computer Languages Quiz"),
           createElement("h1", null, "Test your language knowledge"),
           createElement(
             "p",
             "subtitle",
             "Choose all answers that apply for each question. This quiz uses a React-style component structure while staying in a single standalone HTML file."
           )
         );

         const form = document.createElement("form");
         form.className = "quiz";
         form.noValidate = true;

         quizData.forEach((question) => {
           form.append(QuizQuestion(question));
         });

         const actions = createElement("div", "actions");
         const submit = document.createElement("button");
         submit.className = "submit-btn";
         submit.type = "submit";
         submit.textContent = "Submit quiz";
         actions.append(submit);

         const result = createElement("div", "result");
         result.hidden = true;

         form.addEventListener("submit", (event) => {
           event.preventDefault();
           const selectedCount = Array.from(form.querySelectorAll('input[type="checkbox"]:checked')).length;
           result.textContent = `Submitted with ${selectedCount} selected answer${selectedCount === 1 ? "" : "s"}.`;
           result.hidden = false;
         });

         form.append(actions, result);
         shell.append(hero, form);
         return shell;
       }

       document.getElementById("root").append(App());
     </script>
   </body>
 </html>

